INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '2535cb5b-1965-55a9-98ba-8c8ad879db5c', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Chọn tất cả các phát biểu đúng về cây nhị phân? Select one or more:

Lựa chọn:
- A. Một nút bất kì trên cây không thể có nhiều hơn hai cây con
- B. Bậc ngoại (Outdegree) của bất kì một nút nội luôn bằng 2
- C. Gốc luôn có bậc nội (Indegree) bằng 0
- D. Tất cả các nút là anh em (siblings) sẽ có cây con tương ứng cùng chiều cao.', 1
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '2913d96a-cb8f-5562-adae-65afa47f7a75', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Chọn tất cả các phát biểu đúng về cây? Select one or more:

Lựa chọn:
- A. Anh em (siblings) là những nút có cùng mức (level)
- B. Chiều cao của một cây là mức của nút lá nào đó trên cây sao cho đường đi từ gốc đến nó là dài nhất
- C. Nút cha (parent) là nút có bậc ngoại (outdegree) lớn hơn 0
- D. Mức của một nút là khoảng cách từ nó đến gốc cộng với 1', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '89ce79cb-f21c-504c-8402-b8dcdcf5836c', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Phát biểu nào sau đây đúng? Select one or more:

Lựa chọn:
- A. Cây cân bằng là một cây nhị phân có chỉ số cân bằng tại nút gốc là 0, 1 hoặc -1.
- B. Tất cả các nút trong một cây đều có bậc nội (indegree) bằng 1.
- C. Trong một cây nhị phân, chiều cao của cây là 4 thì tồn tại một cây có số nút là 16.
- D. Trong một cây nhị phân, có thể tồn tại nút có nhiều hơn 2 con.
- E. Tất cả các nút (ngoại trừ nút lá) trong một cây đều có bậc ngoại lớn hơn hoặc bằng 1.', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'e6bb3bac-f792-541c-a329-6bf1f44a7efe', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  '**Câu 4. Chọn tất cả các phát biểu đúng về cây? Select one or more:**

Lựa chọn:
- A. Tất cả các nút lá đều có bậc ngoại (outdegree) là 0
- B. Một cây bao gồm một tập hữu hạn các phần tử (được gọi là nút) và một tập hữu hạn các đường đi có hướng (được gọi là nhánh) kết nối các nút
- C. Một đường đi (path) là một chuỗi các nút liền kề nhau
- D. Tất cả các nút đều có bậc nội (indegree) là 1', 4
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'd28c580a-38c8-52f8-81ff-c6d7685deb26', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Một cây được biểu diễn bằng cách sử dụng ngoặc đơn (parenthetical listing) `A (B (E F) C D (G H I))`. Một hoặc những phát biểu nào sau đây đúng?

Lựa chọn:
- A. Số nút không phải nút nội của cây là 5
- B. D (G H I) là cây con của C
- C. Chiều cao của cây là 3
- D. Hậu duệ của nút B là nút C và nút D
- E. E F G H I là những nút anh em (siblings)', 5
);

