INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'b3ea3b14-d8e9-5b4a-9eec-725411206322', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Phát biểu nào sau đây đúng về cây nhị phân tìm kiếm?

Lựa chọn:
- A. Cây nhị phân tìm kiếm là một cây nhị phân thỏa tất cả các phần tử thuộc cây con bên trái của gốc thì có khóa lớn hơn khóa của gốc, tất cả các phần tử thuộc cây con bên phải của gốc thì có khóa nhỏ hơn hoặc bằng khóa của gốc, và các cây con cũng là cây nhị phân tìm kiếm
