INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'cf72abd0-89f7-5e4f-ada6-00a790b7131e', '96c934ac-4abf-5c3b-a83f-0900ed524ca0',
  'Trong trường hợp nào sau đây, độ phức tạp của việc tìm kiếm trên cây nhị phân tìm kiếm có N nút là $O(1)$? Select one:

